query:
UPDATE services SET benefits = JSON_ARRAY_APPEND(benefits, '$', JSON_OBJECT('title', 'Permits and City Coordination', 'desc', 'We manage all required permits and liaise directly with the City of London and surrounding municipalities, including the PDC renewal program at $7,250 flat rate.'), '$', JSON_OBJECT('title', 'Free Camera Inspection Included', 'desc', 'Every sewer repair starts with a free video camera inspection. You see the footage on site before any work begins, so there are no surprises.')) WHERE slug = 'sewer-repair-installation';

UPDATE services SET benefits = JSON_ARRAY_APPEND(benefits, '$', JSON_OBJECT('title', 'High-Pressure Combination Unit', 'desc', 'Our combination vac and power flushing truck clears blockages that standard drain snakes cannot reach, and removes the debris in the same pass.'), '$', JSON_OBJECT('title', 'Maintenance Programs Available', 'desc', 'Recurring drain cleaning on a scheduled basis prevents blockages before they happen. We offer maintenance programs for residential and commercial properties.')) WHERE slug = 'drain-cleaning';

UPDATE services SET benefits = JSON_ARRAY_APPEND(benefits, '$', JSON_OBJECT('title', 'Full Fleet On-Site', 'desc', 'We own and operate our equipment. Mini excavators, skid steer, dump trailers, and a roll-off truck are available for any size of job without subcontracting.'), '$', JSON_OBJECT('title', 'Surface Restoration Included', 'desc', 'We restore the excavated area after the job is done. Grading, compaction, and surface preparation are part of the service, not an add-on.')) WHERE slug = 'excavation-services';

UPDATE services SET benefits = JSON_ARRAY_APPEND(benefits, '$', JSON_OBJECT('title', 'You Watch the Footage Live', 'desc', 'The camera feeds to a monitor on site. You see exactly what is in your pipe in real time, so you understand the problem before we recommend any solution.'), '$', JSON_OBJECT('title', 'Identifies City vs. Private Responsibility', 'desc', 'The camera travels the full length of your private sewer line to the connection point. If the issue is in the city portion, we identify that clearly and explain your options.')) WHERE slug = 'sewer-camera-inspection';

